values ('bacc1080-2016-4000-8000-000000000003', 'A. 1. Visal lit le texte sans rien comprendre. · 2. Écoutez sans répéter ! · 3. Mon frère passe le bac sans documents. · 4. Madame Dany regarde les marchandises sans rien acheter. · B. 1. Le professeur n''aime ni les retardataires ni les paresseux. · 2. Il ne sait ni expliquer ni discuter. · 3. Ni Paul ni Marie ne sont timides. · 4. Ma sœur ne boit ni bière ni vin.', null, null, null, '[{"content":"A. 1. Visal lit le texte sans rien comprendre."},{"content":"2. Écoutez sans répéter !"},{"content":"3. Mon frère passe le bac sans documents."},{"content":"4. Madame Dany regarde les marchandises sans rien acheter."},{"content":"B. 1. Le professeur n''aime ni les retardataires ni les paresseux."},{"content":"2. Il ne sait ni expliquer ni discuter."},{"content":"3. Ni Paul ni Marie ne sont timides."},{"content":"4. Ma sœur ne boit ni bière ni vin."},{"content":"« sans » + infinitif ou + nom sans article ; « ni… ni… » remplace « pas de » ; avec deux sujets, « Ni… ni… ne » + verbe au pluriel."}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
