insert into public.question_solutions (question_id, answer, correct_choice, numeric_answer, numeric_tolerance, steps, origin, source, verification)
values ('bacc1080-2015-4000-8000-000000000003', 'A. 1. Non, j''ai mal à la poitrine. · 2. Non, je mange du riz. · 3. Oui, un verre d''eau avant le petit déjeuner. · 4. Si, deux heures par semaine. · 5. Oui, j''y vais. · B. 1. Bopha est arrivée en retard parce qu''elle a eu un accident. · 2. Vuth ne va pas se promener parce qu''il est malade. · 3. Comme elle a beaucoup travaillé, Neary est fatiguée.', null, null, null, '[{"content":"A. 1. Non, j''ai mal à la poitrine."},{"content":"2. Non, je mange du riz."},{"content":"3. Oui, un verre d''eau avant le petit déjeuner."},{"content":"4. Si, deux heures par semaine."},{"content":"5. Oui, j''y vais."},{"content":"B. 1. Bopha est arrivée en retard parce qu''elle a eu un accident."},{"content":"2. Vuth ne va pas se promener parce qu''il est malade."},{"content":"3. Comme elle a beaucoup travaillé, Neary est fatiguée."},{"content":"« Comme » se place en tête de phrase et donne la cause d''abord ; « parce que » vient après la conséquence."}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

