insert into public.question_solutions (question_id, answer, correct_choice, numeric_answer, numeric_tolerance, steps, origin, source, verification)
values ('bacc1080-2014-4200-8000-000000000002', 'A. 1. Il a trop travaillé, c''est pourquoi il est malade. · 2. La route n''est pas bonne, aussi faut-il conduire prudemment. · 3. Elle est sérieuse, donc elle réussira à l''examen. · B. 1. Je ne la regarde pas. · 2. Mon père en voudrait un. · 3. Mon amie l''adore. · 4. Le cuisinier va y aller. · 5. Narith en boit.', null, null, null, '[{"content":"A. 1. Il a trop travaillé, c''est pourquoi il est malade."},{"content":"2. La route n''est pas bonne, aussi faut-il conduire prudemment."},{"content":"3. Elle est sérieuse, donc elle réussira à l''examen."},{"content":"B. 1. Je ne la regarde pas."},{"content":"2. Mon père en voudrait un."},{"content":"3. Mon amie l''adore."},{"content":"4. Le cuisinier va y aller."},{"content":"5. Narith en boit."},{"content":"A : « aussi » en tête de proposition entraîne l''inversion du sujet (aussi faut-il)."},{"content":"B : « en » remplace un nom avec du, de la, des, un (en… un) ; « y » remplace un lieu (au supermarché) ; le, la remplacent un nom défini."}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

