insert into public.question_solutions (question_id, answer, correct_choice, numeric_answer, numeric_tolerance, steps, origin, source, verification)
values ('bacc1080-2014-4100-8000-000000000001', 'A. 1. Ma grand-mère peut lire des journaux sans lunettes. · 2. Elle écoute sans rien dire. · 3. C''est la nuit sans étoiles. · B. Intrus : 1. médicament · 2. séjourner · 3. fatigue · 4. Canada · 5. Phnom Penh', null, null, null, '[{"content":"A. 1. Ma grand-mère peut lire des journaux sans lunettes."},{"content":"2. Elle écoute sans rien dire."},{"content":"3. C''est la nuit sans étoiles."},{"content":"B. Intrus : 1. médicament · 2. séjourner · 3. fatigue · 4. Canada · 5. Phnom Penh"},{"content":"B : médicament n''est pas une personne ; séjourner n''est pas un verbe pronominal ; fatigue est un nom (les autres sont des adjectifs) ; le Canada n''est pas en Asie ; Phnom Penh est une ville (les autres sont des pays)."}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

insert into public.questions (id, chapter_id, topic_id, year, type, content, choices, images, difficulty, language, origin, source, verification)
values ('bacc1080-2014-4100-8000-000000000002', 'kh-grade12-science-french-past-papers', null, 2014, 'open', 'II. Grammaire
A. Répondez aux questions en utilisant « Si », « Oui » ou « Non ».
1. Tu ne manges pas de pain ?
…………, je mange du riz.
2. Vous ne buvez pas d''eau le matin ?
…………, un verre d''eau avant le petit déjeuner.
3. Vous apprenez le français ?
…………, deux heures par semaine.

B. Transformez les phrases selon le modèle.
Exemple : Montrez votre photo a Dara. → Montrez-la-lui
1. Donnez ces médicaments à ta sœur.
2. Rendez la monnaie à Neary
3. Montre le chemin à cet enfant.
4. Envoyez de lettres à vos parents.
5. Laisse vos sacs dans la voiture.', '[]'::jsonb, '[]'::jsonb, null, 'fr', 'official-past-paper', 'BacII 2014, first sitting (2014-08-04), science track french, Ministry of Education, Youth and Sport. Typed by Meh Rean from one copy: retyped by ជៀប គន្ធា (github.com/HELMAB/bacii). Not yet checked against the Ministry''s original. Note: The copy gives no points for each part. Both tracks sat the same paper.', 'needs-review')
