insert into public.question_solutions (question_id, answer, correct_choice, numeric_answer, numeric_tolerance, steps, origin, source, verification)
values ('bacc1080-2014-4100-8000-000000000002', 'A. 1. Non, je mange du riz. · 2. Si, un verre d''eau avant le petit déjeuner. · 3. Oui, deux heures par semaine. · B. 1. Donnez-les-lui. · 2. Rendez-la-lui. · 3. Montre-le-lui. · 4. Envoyez-leur-en. · 5. Laisse-les-y.', null, null, null, '[{"content":"A. 1. Non, je mange du riz."},{"content":"2. Si, un verre d''eau avant le petit déjeuner."},{"content":"3. Oui, deux heures par semaine."},{"content":"B. 1. Donnez-les-lui."},{"content":"2. Rendez-la-lui."},{"content":"3. Montre-le-lui."},{"content":"4. Envoyez-leur-en."},{"content":"5. Laisse-les-y."},{"content":"A : « Si » contredit une question négative ; « Non » confirme la négation ; « Oui » répond à une question positive."},{"content":"B : à l''impératif affirmatif, le COD (le, la, les) vient avant le COI (lui, leur) ; « en » remplace « de + nom » et « y » un lieu ; les pronoms se placent après le verbe avec des traits d''union."}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

