insert into public.question_solutions (question_id, answer, correct_choice, numeric_answer, numeric_tolerance, steps, origin, source, verification)
values ('bacc1080-2014-4100-8000-000000000003', 'Texte modèle (IA) : « Une ville touristique que j''aime » — présentation, ce qu''on peut voir, pourquoi je l''aime. Touchez « Show the working » pour le lire.', null, null, null, '[{"content":"Plan : présentation, ce qu''on peut voir, pourquoi je l''aime."},{"content":"J''aime beaucoup Siem Reap, une ville touristique au nord-ouest du Cambodge. Elle est célèbre dans le monde entier grâce aux temples d''Angkor, construits par nos ancêtres il y a plusieurs siècles."},{"content":"Chaque année, des millions de touristes viennent admirer Angkor Vat au lever du soleil, le Bayon et ses visages souriants, et Ta Prohm, où les arbres poussent sur les pierres. En ville, on peut se promener au vieux marché, goûter des plats khmers et regarder des danses Apsara le soir."},{"content":"J''aime Siem Reap parce qu''elle montre la grandeur de notre histoire et la gentillesse des Cambodgiens. Chaque fois que j''y vais, je suis fier d''être khmer."},{"content":"À vérifier : respect de la consigne et du nombre de mots, idées claires, temps des verbes, accords et orthographe."}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
